import React from 'react';

import { useNavigate } from 'react-router-dom';

import CommentsWidget from '@apps/Comments/components/CommentsWidget';
import ObstacleCategoryBadge from '@apps/Obstacles/components/ObstacleCategoryBadge/ObstacleCategoryBadge';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { formatAltitude } from '@helpers/formatHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import HikingObstacleListItem from './HikingObstacleListItem';
import { getUrlFromObstacleType } from '../../Obstacles/@mappers/obstacles.url.mapper';
import { obstacleTypeNameResource } from '../../Obstacles/@resources/obstacles.resource';
import { getOneObstacleAsync } from '../../Obstacles/@services/obstacles.service';
import { IObstacle } from '../../Obstacles/@types/obstacles.types';
import { getHikingDataAsync } from '../@services/hiking.service';
import { getHikingObstaclesList } from '../@services/hikingObstacles.service';
import { getHikingAccessGroupAsync } from '../@services/hikingRules.service';
import { HikingAccessGroup } from '../@types/hiking.rules';
import { IHikingData } from '../@types/hiking.types';
import { IHikingObstacleWithObstacleListItem } from '../@types/hikingObstacles.types';
interface IObstacleInHikingPageProps {
  id_hiking: number;
  id_obstacle: number;
  search?: string;
}

const ObstacleInHikingPage: React.FC<IObstacleInHikingPageProps> = ({ id_hiking, id_obstacle }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [obstacleData, setObstacleData] = React.useState<IObstacle | null>(null);
  const [isLoading, setIsLoading] = React.useState(true);
  const [_canEdit, setCanEdit] = React.useState(false);

  const navigate = useNavigate();

  const [hikingObstacles, setHikingObstacles] = React.useState<
    IHikingObstacleWithObstacleListItem[]
  >([]);

  React.useEffect(() => {
    const start = async () => {
      await getHikingDataAsync(id_hiking).then(setHikingData);
      await getOneObstacleAsync(id_obstacle).then(setObstacleData);
      await getHikingObstaclesList(id_hiking).then((d) =>
        setHikingObstacles(d.filter((x) => x.obstacle.id === id_obstacle)),
      );

      const accessGroup = await getHikingAccessGroupAsync(id_hiking);
      setCanEdit(
        [
          HikingAccessGroup.Full,
          HikingAccessGroup.All,
          HikingAccessGroup.Boss,
          HikingAccessGroup.Routes,
        ].includes(accessGroup),
      );
    };

    start().finally(() => setIsLoading(false));
  }, [id_hiking, id_obstacle]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (!hikingData) {
    return null;
  }

  if (!obstacleData) {
    return <section>wtf</section>;
  }

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name ?? '' },
          { href: `/hiking/${id_hiking}/obstacles`, text: 'Локальные препятствия и POI' },
          {
            href: `/hiking/${id_hiking}/obstacles/${obstacleData.id}`,
            text: obstacleData.name,
            active: true,
          },
        ]}
      />
      <PageHeader
        title={
          <span>
            <h3 className="mb-0">
              {obstacleTypeNameResource[obstacleData.type]}&nbsp;«{obstacleData.name}»
            </h3>
            <small className="text-muted">в походе «{hikingData.name}»</small>
          </span>
        }
      >
        <aside className="d-flex align-items-center">
          <PohButton
            onClick={() =>
              navigate(`/obstacles/${getUrlFromObstacleType(obstacleData.type)}/${obstacleData.id}`)
            }
            variant={ButtonVariant.Light}
            className="ms-2"
          >
            Подробнее
          </PohButton>
        </aside>
      </PageHeader>

      <PohRow>
        <PohCol sm={3}>
          <h5>Общая информация</h5>
          <PohRow className="mb-2">
            <PohCol xs={5} className="text-muted text-sm-end">
              Тип:
            </PohCol>
            <PohCol xs={7}>
              <strong>{obstacleTypeNameResource[obstacleData.type]}</strong>
            </PohCol>
          </PohRow>
          <PohRow className="mb-2">
            <PohCol xs={5} className="text-muted text-sm-end">
              Название:
            </PohCol>
            <PohCol xs={7}>
              <strong>{obstacleData.name}</strong>
            </PohCol>
          </PohRow>
          <PohRow className="mb-2">
            <PohCol xs={5} className="text-muted text-sm-end">
              Категория:
            </PohCol>
            <PohCol xs={7}>
              <ObstacleCategoryBadge category={obstacleData.category} />
            </PohCol>
          </PohRow>
          <PohRow className="mb-2">
            <PohCol xs={5} className="text-muted text-sm-end">
              Высота:
            </PohCol>
            <PohCol xs={7}>{formatAltitude(obstacleData.altitude)}</PohCol>
          </PohRow>
          <PohRow className="mb-2">
            <PohCol xs={5} className="text-muted text-sm-end">
              Регион:
            </PohCol>
            <PohCol xs={7}>{obstacleData.region?.name}</PohCol>
          </PohRow>
        </PohCol>
        <PohCol sm={9}>
          <h5>Сведения о посещении</h5>

          {hikingObstacles.length > 0 ? (
            <PohList
              data={hikingObstacles.map((o) => {
                if (!o.obstacle) return { key: o.id };
                return {
                  key: o.id,
                  children: <HikingObstacleListItem obstacleItem={o} />,

                  action: true,
                  onClick: () => {
                    navigate(`/hiking/${id_hiking}/obstacles/${o.obstacle.id}/${o.id}`);
                  },
                };
              })}
            />
          ) : (
            <Empty height={120}>
              Для этого похода еще не успели добавить информацию посещении
              <br />
              Попробуйте зайти сюда позже
            </Empty>
          )}
        </PohCol>
      </PohRow>
      <CommentsWidget id_hiking={id_hiking} id_obstacle={id_obstacle} />
    </PohContainer>
  );
};

export default ObstacleInHikingPage;
